// Payload from the Bordbistro tracker:
// { event, date, count, summary, replay?, items:[{ id, title, section, register, status, image_path, changes }] }
const LIMIT = 300; // Bluesky: 300 graphemes. Lower it if you add hashtags/links in a later node.

const body = $input.first().json.body || {};
const items = Array.isArray(body.items) ? body.items : [];
if (body.event !== 'menu.changed' || items.length === 0) {
  return []; // nothing to post
}

// Titles per status. Dedupe, keep order of first appearance.
const titles = (...statuses) => [...new Set(
  items.filter(i => statuses.includes(i.status)).map(i => (i.title || '').trim()).filter(Boolean)
)];
const neu = titles('added').concat(titles('returned').map(t => `${t} (wieder da)`));
const entfernt = titles('removed');
const geaendert = titles('changed');

const HEAD = 'Es gibt Änderungen auf der Karte des BoBi:';
const FOOT = 'Die detaillierte Analyse kommt Anfang nächsten Monats auf www.bobi.blog';

// Grapheme count like Bluesky does (emoji/umlauts = 1). Fallback: code points.
const seg = typeof Intl !== 'undefined' && Intl.Segmenter ? new Intl.Segmenter('de', { granularity: 'grapheme' }) : null;
const glen = s => seg ? [...seg.segment(s)].length : [...s].length;

// Sections in display order; `shown` = how many names to print.
const sections = [
  { label: 'Neu', names: neu, shown: neu.length },
  { label: 'Entfernt', names: entfernt, shown: entfernt.length },
  { label: 'Änderungen', names: geaendert, shown: geaendert.length },
];

function render() {
  const lines = [HEAD];
  for (const s of sections) {
    if (!s.names.length) continue;
    const rest = s.names.length - s.shown;
    if (s.shown === 0) lines.push(`${s.label}: ${s.names.length} Artikel`);
    else lines.push(`${s.label}: ${s.names.slice(0, s.shown).join(', ')}${rest ? ` +${rest} weitere` : ''}`);
  }
  lines.push('', FOOT);
  return lines.join('\n');
}

const textFull = render();

// Trim until it fits: drop names from the last section first (Änderungen → Entfernt → Neu).
let text = textFull;
while (glen(text) > LIMIT) {
  const s = [...sections].reverse().find(x => x.shown > 0);
  if (!s) break; // every section already collapsed to counts
  s.shown -= 1;
  text = render();
}
if (glen(text) > LIMIT) text = [...text].slice(0, LIMIT - 1).join('') + '…'; // pathological safety net

return [{
  json: {
    text,                 // fits LIMIT — post this
    textFull,             // untruncated — for channels without a limit
    length: glen(text),
    truncated: text !== textFull,
    date: body.date,
    count: items.length,
    replay: body.replay === true, // true when re-sent from /admin for development
    neu, entfernt, geaendert,
  },
}];
